import {addMaintenanceDays,validMaintenanceDate,validMaintenanceRange} from '@/lib/maintenance';
import type {ReportCell} from '@/lib/report-export';

export const turnoverStates=['queued','in_progress','awaiting_inspection','completed','cancelled'] as const;
export type TurnoverState=typeof turnoverStates[number];
export const turnoverStateLabel:Record<TurnoverState,string>={queued:'Queued',in_progress:'Cleaning in progress',awaiting_inspection:'Awaiting manager inspection',completed:'Completed after inspection',cancelled:'Cancelled'};
export const turnoverActions=['assign','set_due_date','start','submit_cleaning','approve_inspection','return_for_cleaning','cancel'] as const;
export type TurnoverAction=typeof turnoverActions[number];
export const turnoverActionLabel:Record<TurnoverAction,string>={assign:'Assign work',set_due_date:'Change due date',start:'Start cleaning',submit_cleaning:'Submit cleaning for inspection',approve_inspection:'Approve inspection and mark Clean',return_for_cleaning:'Return for cleaning',cancel:'Cancel task and leave Dirty'};
export const turnoverKey=(actor:string,tenant:string,property:string)=>'iratepilot-pms-pending-turnover:'+actor+':'+tenant+':'+property;
export const isTurnoverUuid=(value:unknown):value is string=>typeof value==='string'&&/^[a-f0-9]{8}(-[a-f0-9]{4}){3}-[a-f0-9]{12}$/i.test(value);
export const isTurnoverVersion=(value:unknown):value is number=>Number.isSafeInteger(value)&&Number(value)>0;
export function turnoverDueLabel(dueDate:string,businessDate:string){if(!validMaintenanceDate(dueDate)||!validMaintenanceDate(businessDate))return 'Due date unavailable';return dueDate<businessDate?'Overdue':dueDate===businessDate?'Due today':'Due '+dueDate}
export function validTurnoverReportRange(start:string,end:string){return validMaintenanceRange(start,end)}
export function turnoverReason(value:unknown):value is string{return typeof value==='string'&&value===value.trim()&&value.length>=4&&value.length<=500&&!Array.from(value).some(c=>c.charCodeAt(0)<32||c.charCodeAt(0)===127)}
export function turnoverNote(value:unknown):value is string{return typeof value==='string'&&value.length<=1000&&!Array.from(value).some(c=>(c.charCodeAt(0)<32&&!['\n','\t'].includes(c))||c.charCodeAt(0)===127)}
export type TurnoverEvent={id:string;action:string;actor_id:string;recorded_at:string;from_version:number|null;to_version:number;from_state:TurnoverState|null;to_state:TurnoverState;work_generation:number;room_version_before:number;room_version_after:number;details:Record<string,unknown>};
export type TurnoverTask={id:string;room_id:string;room_label:string;room_type_id:string;room_type_name:string;room_state_version:number;housekeeping:'Clean'|'Dirty'|'Inspect';version:number;work_generation:number;state:TurnoverState;assignee_id:string|null;assignee_label:string|null;assignee_current_member:boolean;due_date:string;created_at:string;created_by:string;created_time_zone:string;created_room_label:string;created_room_type_id:string;creation_operating_model:'hotel'|'whole_home';origin_kind:'checkout'|'room_move'|'manual'|'readiness_dirty';checklist_version:1;checklist:{key:string;label:string}[];started_at:string|null;started_by:string|null;submitted_at:string|null;submitted_by:string|null;submitted_room_version:number|null;submission:null|{checklist:Record<string,true>;note:string};inspected_at:string|null;inspected_by:string|null;closed_at:string|null;closed_by:string|null;close_reason:string|null;occupied_reservation_id:string|null;blocked_reasons:string[];events:TurnoverEvent[]};
export type TurnoverList={property_id:string;time_zone:string;business_date:string;role:string;can_manage:boolean;generated_at:string;period:{start:string;end:string;end_exclusive:true};open_tasks:TurnoverTask[];closed_tasks:TurnoverTask[];eligible_assignees:{user_id:string;label:string;role:string;is_self:boolean}[];projected_departures:{reservation_id:string;room_id:string|null;room_label:string|null;room_type_id:string;room_type_name:string;guest_name:string|null;status:'Confirmed'|'In house';scheduled_departure:string;checked_out_at:null;physically_occupied:boolean;projection_only:true}[];arrival_demand:{stay_date:string;room_type_id:string;room_type_name:string;confirmed_arrivals:number;assigned_arrivals:number}[];summary:{open:number;queued:number;in_progress:number;awaiting_inspection:number;due_today:number;overdue:number;blocked_occupied:number;blocked_maintenance:number;invalid_assignee:number;completed_in_period:number;cancelled_in_period:number};definitions:Record<string,string>};
export type TurnoverDetails={assignee_id:string|null;reason:string}|{due_date:string;reason:string}|Record<string,never>|{checklist:Record<string,true>;note:string}|{work_reviewed:true;room_ready:true;note:string}|{reason:string};
type Expected={p_request:string;p_expected_room_version:number;p_expected_business_date:string};
export type CreateTurnoverCommand=Expected&{p_room:string;p_due_date:string;p_assignee:string|null;p_reason:string};
