 if(value.kind==='create')return exactKeys(p,['p_request','p_expected_room_version','p_expected_business_date','p_room','p_due_date','p_assignee','p_reason'])&&p.p_room===r.room_id&&r.task_id===null&&r.task_version===null&&r.work_generation===null&&r.checklist_keys.length===0&&nullableUuid(p.p_assignee)&&validMaintenanceDate(p.p_due_date)&&p.p_due_date>=p.p_expected_business_date&&p.p_due_date<=addMaintenanceDays(p.p_expected_business_date,366)&&turnoverReason(p.p_reason);
 return value.kind==='update'&&exactKeys(p,['p_request','p_expected_room_version','p_expected_business_date','p_task','p_expected_task_version','p_action','p_details'])&&isTurnoverUuid(p.p_task)&&p.p_task===r.task_id&&isTurnoverVersion(p.p_expected_task_version)&&p.p_expected_task_version===r.task_version&&isTurnoverVersion(r.work_generation)&&turnoverActions.includes(p.p_action as TurnoverAction)&&validTurnoverDetails(p.p_action as TurnoverAction,p.p_details,r.checklist_keys as string[],p.p_expected_business_date);
