export function turnoverExport(data:TurnoverList,kind:'open'|'history'|'events'|'planning',propertyName:string):ReportCell[][]{
 const metadata:ReportCell[][]=[['iRatePilot PMS','Turnover '+kind],['Property',propertyName],['Property ID',data.property_id],['Property time zone',data.time_zone],['Property business date',data.business_date],['History / projection start',data.period.start],['History / projection end (exclusive)',data.period.end],['Generated at',data.generated_at],['Open task basis','All open tasks, including work due before this report period.'],['History basis','Closed timestamps within the selected dates in the current property time zone; original creation zone retained.'],['Planning basis','Scheduled departures and arrival demand are projections. They do not prove checkout, create cleaning work or assign unassigned arrivals to a room.'],['Readiness basis','Cleaning submission requires checklist attestation; only manager inspection marks Clean. This is an operational work log, not payroll, a fee receipt or earned revenue.'],[]];
 const tasks=kind==='open'?data.open_tasks:kind==='history'?data.closed_tasks:[...data.open_tasks,...data.closed_tasks];
 if(kind==='events')return [...metadata,['Task ID','Room','Event ID','Action','Actor','Recorded at','From task version','To task version','From state','To state','Work generation','Room version before','Room version after','Details'],...tasks.flatMap(task=>task.events.map(event=>[task.id,task.room_label,event.id,event.action,event.actor_id,event.recorded_at,event.from_version,event.to_version,event.from_state,event.to_state,event.work_generation,event.room_version_before,event.room_version_after,JSON.stringify(event.details)]))];
 if(kind==='planning')return [...metadata,['Kind','Reservation ID','Room / type','Scheduled date','Status','Physically occupied','Confirmed arrivals','Assigned arrivals'],...data.projected_departures.map(p=>['Projected departure — checkout not recorded',p.reservation_id,p.room_label??p.room_type_name,p.scheduled_departure,p.status,p.physically_occupied?'Yes':'No',null,null]),...data.arrival_demand.map(row=>['Arrival demand',null,row.room_type_name,row.stay_date,'Confirmed',null,row.confirmed_arrivals,row.assigned_arrivals])];
 return [...metadata,['Task ID','Room ID','Current room label','Created room label','State','Task version','Work generation','Origin','Assignee ID','Assignee label','Assignee current member','Due date','Due status','Created at','Created by','Creation time zone','Creation operating model','Started at','Started by','Submitted at','Submitted by','Submitted room version','Inspected at','Inspected by','Closed at','Closed by','Close reason','Current housekeeping','Current room revision','Blockers'],...tasks.map(task=>[task.id,task.room_id,task.room_label,task.created_room_label,task.state,task.version,task.work_generation,task.origin_kind,task.assignee_id,task.assignee_label,task.assignee_current_member?'Yes':'No',task.due_date,turnoverDueLabel(task.due_date,data.business_date),task.created_at,task.created_by,task.created_time_zone,task.creation_operating_model,task.started_at,task.started_by,task.submitted_at,task.submitted_by,task.submitted_room_version,task.inspected_at,task.inspected_by,task.closed_at,task.closed_by,task.close_reason,task.housekeeping,task.room_state_version,task.blocked_reasons.join('; ')])];
}
